// src/pages/Opportunities.jsx
import React, { useState, useEffect } from 'react';
import { Search, MapPin, Briefcase, Filter } from 'lucide-react';

const Opportunities = () => {
  const [filterWilaya, setFilterWilaya] = useState('');
  const [filterTech, setFilterTech] = useState('');

  const algeriaWilayas = ["Algiers", "Constantine", "Oran", "Sétif", "Annaba", "Batna"];
  const techs = ["React", "Java", "Python", "Node.js", "Flutter", "UI/UX"];

  const styles = {
    container: {
      backgroundColor: '#f8fafc',
      minHeight: '100vh',
      padding: '40px 20px',
      fontFamily: "'Inter', sans-serif",
    },
    header: {
      textAlign: 'center',
      marginBottom: '40px',
    },
    title: {
      fontSize: '32px',
      color: '#1e293b',
      fontWeight: '800',
      marginBottom: '10px',
    },
    filterBar: {
      backgroundColor: '#ffffff',
      padding: '24px',
      borderRadius: '16px',
      boxShadow: '0 4px 15px rgba(0, 0, 0, 0.05)',
      maxWidth: '1000px',
      margin: '0 auto 40px auto',
      display: 'flex',
      flexWrap: 'wrap',
      gap: '20px',
      alignItems: 'center',
    },
    inputGroup: {
      flex: '1',
      minWidth: '200px',
    },
    label: {
      display: 'block',
      fontSize: '14px',
      fontWeight: '600',
      color: '#64748b',
      marginBottom: '8px',
    },
    select: {
      width: '100%',
      padding: '12px',
      borderRadius: '10px',
      border: '1px solid #e2e8f0',
      backgroundColor: '#f1f5f9',
      color: '#475569',
      fontSize: '15px',
      outline: 'none',
      cursor: 'pointer',
    },
    grid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
      gap: '25px',
      maxWidth: '1200px',
      margin: '0 auto',
    },
    card: {
      backgroundColor: '#ffffff',
      borderRadius: '20px',
      padding: '24px',
      boxShadow: '0 10px 25px rgba(0, 0, 0, 0.03)',
      transition: 'transform 0.3s ease, shadow 0.3s ease',
      border: '1px solid #f1f5f9',
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'space-between',
    },
    badge: {
      padding: '6px 12px',
      borderRadius: '8px',
      fontSize: '12px',
      fontWeight: '700',
      textTransform: 'uppercase',
    },
    applyBtn: {
      width: '100%',
      padding: '12px',
      backgroundColor: '#2563eb',
      color: '#ffffff',
      border: 'none',
      borderRadius: '12px',
      fontWeight: '600',
      cursor: 'pointer',
      marginTop: '20px',
      transition: 'background 0.3s ease',
    }
  };

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1 style={styles.title}>Explore Opportunities</h1>
        <p style={{ color: '#64748b' }}>Find the perfect internship that matches your skills</p>
      </header>

      {/* Modern Filter Bar */}
      <div style={styles.filterBar}>
        <div style={styles.inputGroup}>
          <label style={styles.label}><MapPin size={14} style={{marginRight: 5}}/> Select Wilaya</label>
          <select 
            style={styles.select}
            value={filterWilaya}
            onChange={(e) => setFilterWilaya(e.target.value)}
          >
            <option value="">All Regions</option>
            {algeriaWilayas.map(w => <option key={w} value={w}>{w}</option>)}
          </select>
        </div>

        <div style={styles.inputGroup}>
          <label style={styles.label}><Filter size={14} style={{marginRight: 5}}/> Technology</label>
          <select 
            style={styles.select}
            value={filterTech}
            onChange={(e) => setFilterTech(e.target.value)}
          >
            <option value="">All Technologies</option>
            {techs.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>

        <button style={{...styles.applyBtn, width: 'auto', marginTop: 22, padding: '12px 30px'}}>
          Search
        </button>
      </div>
      {/* Opportunities Grid */}
      <div style={styles.grid}>
        {[1, 2, 3].map((item) => (
          <div key={item} style={styles.card} className="opportunity-card">
            <div>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '15px' }}>
                <span style={{ ...styles.badge, backgroundColor: '#dcfce7', color: '#166534' }}>Full-Time</span>
                <span style={{ color: '#94a3b8', fontSize: '13px' }}>2 days ago</span>
              </div>
              <h3 style={{ fontSize: '20px', fontWeight: '700', color: '#1e293b', marginBottom: '8px' }}>
                Full-Stack Developer Internship
              </h3>
              <p style={{ color: '#64748b', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '5px' }}>
                <Briefcase size={14} /> TechSolutions DZ
              </p>
              <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px', display: 'flex', alignItems: 'center', gap: '5px' }}>
                <MapPin size={14} /> Constantine, Algeria
              </p>
              
              <div style={{ display: 'flex', gap: '8px', marginTop: '15px' }}>
                <span style={{ background: '#f1f5f9', padding: '4px 10px', borderRadius: '6px', fontSize: '12px', color: '#475569' }}>React</span>
                <span style={{ background: '#f1f5f9', padding: '4px 10px', borderRadius: '6px', fontSize: '12px', color: '#475569' }}>Node.js</span>
              </div>
            </div>

            <button style={styles.applyBtn}>Apply Now</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Opportunities;
